# Re‑define the simulated function (simple collision detection).
import math, re
from typing import Dict, List, Any, Set, Tuple

def _parse_obj_id(obj_field: str) -> str:
    return obj_field.split()[0]

def _collision_distance_threshold() -> float:
    return 1.0

def _build_motion_log_matrix(doc: Dict[str, Any], scope: str) -> Dict[int, Dict[str, Dict[str, float]]]:
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    matrix: Dict[int, Dict[str, Dict[str, float]]] = {}
    if not motion_node or motion_node["kind"] != "table":
        return matrix
    for _, row in table_rows(motion_node):
        try:
            frame = int(row["frame"])
        except ValueError:
            continue
        oid = _parse_obj_id(row["object"])
        try:
            x = float(row["x"])
            y = float(row["y"])
            vx = float(row["vx"])
            vy = float(row["vy"])
        except (KeyError, ValueError):
            continue
        matrix.setdefault(frame, {}).setdefault(oid,{})
        matrix[frame][oid]["x"]=x; matrix[frame][oid]["y"]=y
        matrix[frame][oid]["vx"]=vx; matrix[frame][oid]["vy"]=vy
    return matrix

def _collision_pairs(frame_dict: Dict[str,Dict[str,float]], ids: Set[str]) -> List[Tuple[str,str]]:
    res=[]; objs=[o for o in frame_dict if o in ids]
    for i in range(len(objs)):
        for j in range(i+1,len(objs)):
            o1=objs[i];o2=objs[j]
            d1=frame_dict[o1]; d2=frame_dict[o2]
            dx=d1["x"]-d2["x"]; dy=d1["y"]-d2["y"]
            if dx*dx+dy*dy <= _collision_distance_threshold()**2:
                res.append((o1,o2))
    return res

def simulate(doc: Dict[str,Any], scope:str, inputs:List[Dict[str,Any]], params:Dict[str,Any], start:float=None, horizon:float=None):
    obj_ids={inp["entities"][0] for inp in inputs if inp["kind"]=="arrival"}
    mlog=_build_motion_log_matrix(doc,scope)
    if start is None: start=0.0
    rec_end= recorded_end(doc, scope)
    if horizon is None: horizon=float(rec_end) if rec_end is not None else start
    start_f=int(math.floor(start)); horizon_f=int(math.ceil(horizon))
    out=[]
    rep=set()
    for f in range(start_f,horizon_f+1):
        if f not in mlog: continue
        for a,b in _collision_pairs(mlog[f],obj_ids):
            pair=tuple(sorted([a,b]))
            if pair in rep: continue
            rep.add(pair)
            out.append({"time":float(f),"kind":"collision","entities":[a,b],"value":None,"src":[]})
    if start<=float(rec_end)<=horizon:
        out.append({"time":float(rec_end),"kind":"video_end","entities":[],"value":None,"src":[]})
    out.sort(key=lambda r:r["time"])
    return out

